using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// Configuration
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "sk-placeholder";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";
var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing";

Console.WriteLine($"Research Agent Starting...");
Console.WriteLine($"Researching topic: {topic}");
Console.WriteLine(new string('-', 50));

// Set up the AI client with tools
var openAiClient = new OpenAIClient(openAiKey);
IChatClient innerClient = openAiClient.GetChatClient(model).AsIChatClient();

var notes = new ResearchNotes();

IChatClient agent = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

// Define tools
var searchTool = AIFunctionFactory.Create(
    (string query) =>
    {
        Console.WriteLine($"  [Search] Querying: {query}");
        return WebSearchSimulator.Search(query);
    },
    "web_search",
    "Searches the web for information on a given query. Returns a list of relevant results with titles, snippets, and URLs.");

var addNoteTool = AIFunctionFactory.Create(
    ([Description("A concise note capturing a key finding")] string note,
     [Description("The source URL or reference")] string source) =>
    {
        notes.Add(note, source);
        Console.WriteLine($"  [Note Added] {note[..Math.Min(note.Length, 60)]}...");
        return $"Note saved. Total notes: {notes.Count}";
    },
    "add_note",
    "Saves a research note with its source for later summarization.");

var getNotesTool = AIFunctionFactory.Create(
    () =>
    {
        return notes.GetAll();
    },
    "get_notes",
    "Retrieves all saved research notes to help compose a summary.");

var chatOptions = new ChatOptions
{
    Tools = [searchTool, addNoteTool, getNotesTool]
};

// Run the agent
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to thoroughly research a given topic using web search,
        take detailed notes on key findings, and then produce a comprehensive summary.

        Follow this process:
        1. Search for the topic using multiple relevant queries (at least 3 different searches)
        2. For each useful finding, save a note with the source
        3. After gathering enough information, retrieve your notes and write a final summary

        Be thorough and cite your sources in the final summary.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
};

var response = await agent.GetResponseAsync(messages, chatOptions);

Console.WriteLine(new string('-', 50));
Console.WriteLine("RESEARCH SUMMARY:");
Console.WriteLine(new string('-', 50));
Console.WriteLine(response.Text);
Console.WriteLine(new string('-', 50));
Console.WriteLine($"Total notes collected: {notes.Count}");

// --- Supporting classes ---

public class ResearchNotes
{
    private readonly List<(string Note, string Source, DateTime Timestamp)> _notes = [];

    public int Count => _notes.Count;

    public void Add(string note, string source)
    {
        _notes.Add((note, source, DateTime.UtcNow));
    }

    public string GetAll()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"[{i + 1}] {n.Note}\n    Source: {n.Source}\n    Saved: {n.Timestamp:u}"));
    }
}

public static class WebSearchSimulator
{
    // Simulates web search results for demonstration purposes.
    // Replace with a real search API (Bing, Google, Tavily, etc.) for production use.
    public static string Search(string query)
    {
        var results = new[]
        {
            new
            {
                Title = $"Latest Research on {query} - Science Daily",
                Snippet = $"Recent studies have shown significant breakthroughs in {query}. " +
                          "Researchers at leading universities have published new findings that could " +
                          "transform our understanding of the field.",
                Url = $"https://www.sciencedaily.com/search?query={Uri.EscapeDataString(query)}"
            },
            new
            {
                Title = $"{query} - Wikipedia Overview",
                Snippet = $"{query} encompasses a broad range of topics and applications. " +
                          "The field has evolved significantly over the past decade with key contributions " +
                          "from both academic and industry researchers.",
                Url = $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}"
            },
            new
            {
                Title = $"Industry Applications of {query} - TechReview",
                Snippet = $"Major technology companies are investing heavily in {query}. " +
                          "Practical applications are emerging in healthcare, finance, and manufacturing " +
                          "sectors with promising early results.",
                Url = $"https://www.techreview.com/topic/{Uri.EscapeDataString(query)}"
            },
            new
            {
                Title = $"Future Directions in {query} - Nature",
                Snippet = $"A comprehensive review of {query} highlights emerging trends and " +
                          "challenges. Experts predict major milestones within the next 5-10 years " +
                          "that could revolutionize the field.",
                Url = $"https://www.nature.com/articles/{Uri.EscapeDataString(query)}-review"
            }
        };

        return string.Join("\n\n", results.Select(r =>
            $"Title: {r.Title}\nSnippet: {r.Snippet}\nURL: {r.Url}"));
    }
}

